// Set configuration variables & calculate cutoff date (7 days ago)
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [
  {
    json: {
      GITHUB_OWNER: "claude-builders-bounty",
      GITHUB_REPO: "claude-builders-bounty",
      WEBHOOK_URL: "https://discord.com/api/webhooks/YOUR_WEBHOOK_URL",
      LANGUAGE: "EN", // "EN" or "FR"
      ANTHROPIC_API_KEY: "sk-ant-YOUR_API_KEY",
      GITHUB_TOKEN: "", // Optional GitHub Token for higher rate limits
      since_date: sevenDaysAgo.toISOString()
    }
  }
];

const config = $('Set Configuration').first().json;
const sinceDate = new Date(config.since_date);

// Process Commits
const commitsRaw = $('Fetch Commits').all();
const commits = [];
for (const item of commitsRaw) {
  if (item.json && item.json.commit) {
    commits.push({
      sha: item.json.sha ? item.json.sha.substring(0, 7) : '',
      author: item.json.commit.author ? item.json.commit.author.name : 'Unknown',
      message: item.json.commit.message ? item.json.commit.message.split('\n')[0] : ''
    });
  }
}

// Process Closed Issues (excluding PRs)
const issuesRaw = $('Fetch Closed Issues').all();
const closedIssues = [];
for (const item of issuesRaw) {
  if (item.json && item.json.number && !item.json.pull_request) {
    const closedAt = item.json.closed_at ? new Date(item.json.closed_at) : null;
    if (closedAt && closedAt >= sinceDate) {
      closedIssues.push({
        number: item.json.number,
        title: item.json.title,
        user: item.json.user ? item.json.user.login : 'Unknown'
      });
    }
  }
}

// Process Merged PRs
const prsRaw = $('Fetch Merged PRs').all();
const mergedPRs = [];
for (const item of prsRaw) {
  if (item.json && item.json.number && item.json.merged_at) {
    const mergedAt = new Date(item.json.merged_at);
    if (mergedAt >= sinceDate) {
      mergedPRs.push({
        number: item.json.number,
        title: item.json.title,
        user: item.json.user ? item.json.user.login : 'Unknown'
      });
    }
  }
}

const lang = (config.LANGUAGE || 'EN').toUpperCase();
const repo = `${config.GITHUB_OWNER}/${config.GITHUB_REPO}`;

let userPrompt = "";

if (lang === "FR") {
  userPrompt = `Générez un résumé hebdomadaire clair, concis et structuré de l'activité du dépôt GitHub "${repo}" pour la semaine écoulée.

Voici les données d'activité récoltées :

### Commits (${commits.length}) :
${commits.length > 0 ? commits.map(c => `- [${c.sha}] ${c.message} (par ${c.author})`).join('\n') : 'Aucun commit cette semaine.'}

### Issues Fermées (${closedIssues.length}) :
${closedIssues.length > 0 ? closedIssues.map(i => `- #${i.number}: ${i.title} (fermée par ${i.user})`).join('\n') : 'Aucune issue fermée cette semaine.'}

### Pull Requests Fusionnées (${mergedPRs.length}) :
${mergedPRs.length > 0 ? mergedPRs.map(p => `- #${p.number}: ${p.title} (fusionnée par ${p.user})`).join('\n') : 'Aucune PR fusionnée cette semaine.'}

Instructions :
1. Rédigez le résumé en Français.
2. Structurez avec des émojis et des sections claires (Vue d'ensemble, Réalisations clés, Stats rapides).
3. Gardez un ton professionnel et enthousiaste. Format Markdown.`;
} else {
  userPrompt = `Generate a clear, concise, and structured weekly summary of development activity for the GitHub repository "${repo}" for the past week.

Here is the collected activity data:

### Commits (${commits.length}):
${commits.length > 0 ? commits.map(c => `- [${c.sha}] ${c.message} (by ${c.author})`).join('\n') : 'No commits this week.'}

### Closed Issues (${closedIssues.length}):
${closedIssues.length > 0 ? closedIssues.map(i => `- #${i.number}: ${i.title} (closed by ${i.user})`).join('\n') : 'No closed issues this week.'}

### Merged Pull Requests (${mergedPRs.length}):
${mergedPRs.length > 0 ? mergedPRs.map(p => `- #${p.number}: ${p.title} (merged by ${p.user})`).join('\n') : 'No merged PRs this week.'}

Instructions:
1. Write the summary in English.
2. Structure with emojis and clear sections (Overview, Key Highlights, Quick Stats).
3. Keep the tone professional and engaging. Format in clean Markdown.`;
}

return [
  {
    json: {
      anthropic_payload: {
        model: "claude-sonnet-4-20250514",
        max_tokens: 1024,
        messages: [
          {
            role: "user",
            content: userPrompt
          }
        ]
      },
      webhook_url: config.WEBHOOK_URL,
      anthropic_api_key: config.ANTHROPIC_API_KEY
    }
  }
];

const response = $input.first().json;
let summaryText = "";

if (response.content && Array.isArray(response.content) && response.content.length > 0) {
  summaryText = response.content.map(c => c.text || '').join('\n');
} else if (response.error) {
  summaryText = `⚠️ Error generating summary from Claude API: ${response.error.message || JSON.stringify(response.error)}`;
} else {
  summaryText = "No summary generated.";
}

const config = $('Format Data & Build Claude Prompt').first().json;

return [
  {
    json: {
      summaryText: summaryText,
      webhook_url: config.webhook_url
    }
  }
];
